import 'package:flutter/material.dart';

void main() => runApp(const UpdateDemoApp());
class UpdateDemoApp extends StatelessWidget { const UpdateDemoApp({super.key}); @override Widget build(BuildContext context) => MaterialApp(debugShowCheckedModeBanner: false, title: 'Firestore Update Demo', theme: ThemeData(colorScheme: ColorScheme.fromSeed(seedColor: const Color(0xff8d50aa)), useMaterial3: true), home: const UpdatePage()); }
class UpdatePage extends StatefulWidget { const UpdatePage({super.key}); @override State<UpdatePage> createState() => _UpdatePageState(); }
class _UpdatePageState extends State<UpdatePage> {
  final List<Map<String, String>> _records = [{'name':'Jordan Lee','role':'Designer','department':'Product'}, {'name':'Taylor Morgan','role':'Developer','department':'Engineering'}];
  void _edit(int index) { final record = _records[index]; final name = TextEditingController(text: record['name']), role = TextEditingController(text: record['role']), department = TextEditingController(text: record['department']); showDialog<void>(context: context, builder: (dialogContext) => AlertDialog(title: const Text('Update employee'), content: SingleChildScrollView(child: Column(mainAxisSize: MainAxisSize.min, children: [TextField(controller: name, decoration: const InputDecoration(labelText: 'Name')), TextField(controller: role, decoration: const InputDecoration(labelText: 'Job title')), TextField(controller: department, decoration: const InputDecoration(labelText: 'Department'))])), actions: [TextButton(onPressed: () => Navigator.pop(dialogContext), child: const Text('Cancel')), FilledButton(onPressed: () { if ([name, role, department].any((c) => c.text.trim().isEmpty)) return; setState(() { record['name'] = name.text.trim(); record['role'] = role.text.trim(); record['department'] = department.text.trim(); }); Navigator.pop(dialogContext); }, child: const Text('Save changes'))])); }
  @override Widget build(BuildContext context) => Scaffold(appBar: AppBar(title: const Text('Update Employee Records')), body: Center(child: ConstrainedBox(constraints: const BoxConstraints(maxWidth: 680), child: ListView(padding: const EdgeInsets.all(16), children: [const Card(child: ListTile(leading: Icon(Icons.cloud_off), title: Text('Simulated Firestore update'), subtitle: Text('Changes exist only until the app closes.'))), const SizedBox(height: 12), ..._records.asMap().entries.map((entry) { final index = entry.key, r = entry.value; return Card(child: ListTile(leading: const CircleAvatar(child: Icon(Icons.person)), title: Text(r['name']!), subtitle: Text('${r['role']} • ${r['department']}'), trailing: IconButton(tooltip: 'Edit ${r['name']}', icon: const Icon(Icons.edit), onPressed: () => _edit(index)))); })]))));
}
